/**
 * Limit how many async tasks run at once, queueing the rest in the order
 * they were started
 *
 * A task must not wait on another run() of the same limiter, since with
 * every slot taken the inner task can never start
 */
export declare class ConcurrencyLimiter {
    #private;
    readonly maxConcurrent: number;
    constructor(maxConcurrent: number);
    run<T>(code: () => Promise<T>): Promise<T>;
}
